false,"service_role":true,"required":true,"expected_owner":"postgres","reason":"Collateral top-up trust correction: verified user ID and blockchain balance supplied only by service Edge."}]$manifest$::jsonb)
AS m(signature text,category text,anon boolean,authenticated boolean,service_role boolean,required boolean,expected_owner text,reason text);
DO $preflight$
DECLARE r record; v_oid oid; v_owner text;
BEGIN
 FOR r IN SELECT * FROM pg_temp.ngoda_rpc_permissions_expected LOOP
  v_oid:=to_regprocedure(r.signature)::oid;
  IF v_oid IS NULL THEN
   IF r.required THEN RAISE EXCEPTION 'REQUIRED_RPC_MISSING: %',r.signature; END IF;
   CONTINUE;
  END IF;
  SELECT pg_get_userbyid(proowner) INTO v_owner FROM pg_proc WHERE oid=v_oid;
  IF v_owner IS DISTINCT FROM r.expected_owner THEN
   RAISE EXCEPTION 'RPC_OWNER_CHANGED: %, expected %, found %',r.signature,r.expected_owner,v_owner;
  END IF;
 END LOOP;
END;
$preflight$;
DO $verify$
DECLARE r record; v_oid oid; v_public boolean;
BEGIN
 FOR r IN SELECT * FROM pg_temp.ngoda_rpc_permissions_expected LOOP
  v_oid:=to_regprocedure(r.signature)::oid;
  IF v_oid IS NULL THEN CONTINUE; END IF;
  IF has_function_privilege('anon',v_oid,'EXECUTE') IS DISTINCT FROM r.anon
     OR has_function_privilege('authenticated',v_oid,'EXECUTE') IS DISTINCT FROM r.authenticated
     OR has_function_privilege('service_role',v_oid,'EXECUTE') IS DISTINCT FROM r.service_role THEN
   RAISE EXCEPTION 'RPC_PERMISSION_VERIFICATION_FAILED: %',r.signature;
  END IF;
  SELECT EXISTS (SELECT 1 FROM pg_proc p,
    LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
    WHERE p.oid=v_oid AND a.grantee=0 AND a.privilege_type='EXECUTE') INTO v_public;
  IF v_public THEN RAISE EXCEPTION 'PUBLIC_EXECUTE_REMAINS: %',r.signature; END IF;
 END LOOP;
END;
$verify$;
SELECT m.category,count(*) AS installed_functions
FROM pg_temp.ngoda_rpc_permissions_expected m
WHERE to_regprocedure(m.signature) IS NOT NULL GROUP BY m.category ORDER BY m.category;
-- New functions outside this reviewed manifest: review separately; do not silently guess grants.
SELECT p.oid::regprocedure AS unmanaged_function,pg_get_userbyid(p.proowner) AS owner,
 p.prosecdef AS security_definer,p.proacl AS grants
FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
WHERE n.nspname='public' AND p.prokind IN ('f','p')
AND NOT EXISTS(SELECT 1 FROM pg_temp.ngoda_rpc_permissions_expected m WHERE to_regprocedure(m.signature)::oid=p.oid)
ORDER BY 1;
COMMIT;
